619: 	public static boolean hit( Char attacker, Char defender, float accMulti, boolean magic ) {
620: 		float acuStat = attacker.attackSkill( defender );
621: 		float defStat = defender.defenseSkill( attacker );
622: 
623: 		if (defender instanceof Hero && ((Hero) defender).damageInterrupt){
624: 			((Hero) defender).interrupt();
625: 		}
626: 
627: 		//invisible chars always hit (for the hero this is surprise attacking)
628: 		if (attacker.invisible > 0 && attacker.canSurpriseAttack()){
629: 			acuStat = INFINITE_ACCURACY;
630: 		}
631: 
632: 		if (defender.buff(MonkEnergy.MonkAbility.Focus.FocusBuff.class) != null){
633: 			defStat = INFINITE_EVASION;
634: 		}
635: 
636: 		//if accuracy or evasion are large enough, treat them as infinite.
637: 		//note that infinite evasion beats infinite accuracy
638: 		if (defStat >= INFINITE_EVASION){
639: 			hitMissIcon = FloatingText.getMissReasonIcon(attacker, acuStat, defender, INFINITE_EVASION);
640: 			return false;
641: 		} else if (acuStat >= INFINITE_ACCURACY){
642: 			hitMissIcon = FloatingText.getHitReasonIcon(attacker, INFINITE_ACCURACY, defender, defStat);
643: 			return true;
644: 		}
645: 
646: 		float acuRoll = Random.Float( acuStat );
647: 		if (attacker.buff(Bless.class) != null) acuRoll *= 1.25f;
648: 		if (attacker.buff(  Hex.class) != null) acuRoll *= 0.8f;
649: 		if (attacker.buff( Daze.class) != null) acuRoll *= 0.5f;
650: 		for (ChampionEnemy buff : attacker.buffs(ChampionEnemy.class)){
651: 			acuRoll *= buff.evasionAndAccuracyFactor();
652: 		}
653: 		acuRoll *= AscensionChallenge.statModifier(attacker);
654: 		if (Dungeon.hero.heroClass != HeroClass.CLERIC
655: 				&& Dungeon.hero.hasTalent(Talent.BLESS)
656: 				&& attacker.alignment == Alignment.ALLY){
657: 			// + 3%/5%
658: 			acuRoll *= 1.01f + 0.02f*Dungeon.hero.pointsInTalent(Talent.BLESS);
659: 		}
660: 		acuRoll *= accMulti;
661: 
662: 		float defRoll = Random.Float( defStat );
663: 		if (defender.buff(Bless.class) != null) defRoll *= 1.25f;
664: 		if (defender.buff(  Hex.class) != null) defRoll *= 0.8f;
665: 		if (defender.buff( Daze.class) != null) defRoll *= 0.5f;
666: 		for (ChampionEnemy buff : defender.buffs(ChampionEnemy.class)){
667: 			defRoll *= buff.evasionAndAccuracyFactor();
668: 		}
669: 		defRoll *= AscensionChallenge.statModifier(defender);
670: 		if (Dungeon.hero.heroClass != HeroClass.CLERIC
671: 				&& Dungeon.hero.hasTalent(Talent.BLESS)
672: 				&& defender.alignment == Alignment.ALLY){
673: 			// + 3%/5%
674: 			defRoll *= 1.01f + 0.02f*Dungeon.hero.pointsInTalent(Talent.BLESS);
675: 		}
676: 		defRoll *= FerretTuft.evasionMultiplier();
677: 
678: 		if (acuRoll >= defRoll){
679: 			hitMissIcon = FloatingText.getHitReasonIcon(attacker, acuRoll, defender, defRoll);
680: 			return true;
681: 		} else {
682: 			hitMissIcon = FloatingText.getMissReasonIcon(attacker, acuRoll, defender, defRoll);
683: 			return false;
684: 		}

510: 	@Override
511: 	public int attackSkill( Char target ) {
512: 		KindOfWeapon wep = belongings.attackingWeapon();
513: 		
514: 		float accuracy = 1;
515: 		accuracy *= RingOfAccuracy.accuracyMultiplier( this );
516: 		
517: 		//precise assault and liquid agility
518: 		if (!(wep instanceof MissileWeapon)) {
519: 			if ((hasTalent(Talent.PRECISE_ASSAULT) || hasTalent(Talent.LIQUID_AGILITY))
520: 					//does not trigger on ability attacks
521: 					&& belongings.abilityWeapon != wep && buff(MonkEnergy.MonkAbility.UnarmedAbilityTracker.class) == null){
522: 
523: 				//non-duelist benefit for precise assault, can stack with liquid agility
524: 				if (heroClass != HeroClass.DUELIST) {
525: 					//persistent +10%/20%/30% ACC for other heroes
526: 					accuracy *= 1f + 0.1f * pointsInTalent(Talent.PRECISE_ASSAULT);
527: 				}
528: 
529: 				if (wep instanceof Flail && buff(Flail.SpinAbilityTracker.class) != null){
530: 					//do nothing, this is not a regular attack so don't consume talent fx
531: 				} else if (wep instanceof Crossbow && buff(Crossbow.ChargedShot.class) != null){
532: 					//do nothing, this is not a regular attack so don't consume talent fx
533: 				} else if (buff(Talent.PreciseAssaultTracker.class) != null) {
534: 					// 2x/5x/inf. ACC for duelist if she just used a weapon ability
535: 					switch (pointsInTalent(Talent.PRECISE_ASSAULT)){
536: 						default: case 1:
537: 							accuracy *= 2; break;
538: 						case 2:
539: 							accuracy *= 5; break;
540: 						case 3:
541: 							accuracy *= Float.POSITIVE_INFINITY; break;
542: 					}
543: 				} else if (buff(Talent.LiquidAgilACCTracker.class) != null){
544: 					// 3x/inf. ACC, depending on talent level
545: 					accuracy *= pointsInTalent(Talent.LIQUID_AGILITY) == 2 ? Float.POSITIVE_INFINITY : 3f;
546: 					Talent.LiquidAgilACCTracker buff = buff(Talent.LiquidAgilACCTracker.class);
547: 					buff.uses--;
548: 				}
549: 			}
550: 		} else {
551: 			if (buff(Momentum.class) != null && buff(Momentum.class).freerunning()){
552: 				accuracy *= 1f + pointsInTalent(Talent.PROJECTILE_MOMENTUM)/2f;
553: 			}
554: 		}
555: 
556: 		if (buff(Scimitar.SwordDance.class) != null){
557: 			accuracy *= 1.50f;
558: 		}
559: 		
560: 		if (!RingOfForce.fightingUnarmed(this)) {
561: 			return Math.max(1, Math.round(attackSkill * accuracy * wep.accuracyFactor( this, target )));
562: 		} else {
563: 			return Math.max(1, Math.round(attackSkill * accuracy));
564: 		}

289: 	public float accuracyFactor(Char owner, Char target) {
290: 		
291: 		int encumbrance = 0;
292: 		
293: 		if( owner instanceof Hero ){
294: 			encumbrance = STRReq() - ((Hero)owner).STR();
295: 		}
296: 
297: 		float ACC = this.ACC;
298: 
299: 		if (owner.buff(Wayward.WaywardBuff.class) != null && enchantment instanceof Wayward){
300: 			ACC /= 5;
301: 		}
302: 
303: 		return encumbrance > 0 ? (float)(ACC / Math.pow( 1.5, encumbrance )) : ACC;

