73: 	private static float tier(int str){
74: 		float tier = Math.max(1, (str - 8)/2f);
75: 		//each str point after 18 is half as effective
76: 		if (tier > 5){
77: 			tier = 5 + (tier - 5) / 2f;
78: 		}
