82: 	public static int damageRoll( Hero hero ){
83: 		//level can be 0 while still using a ring, so we specifically check for the presence of a ring of force
84: 		boolean usingForce = hero.buff(Force.class) != null;
85: 		if (hero.buff(SpiritForm.SpiritFormBuff.class) != null && hero.buff(SpiritForm.SpiritFormBuff.class).ring() instanceof RingOfForce){
86: 			usingForce = true;
87: 		}
88: 		//and ignore that presence if using monk abilities
89: 		if (hero.buff(MonkEnergy.MonkAbility.UnarmedAbilityTracker.class) != null){
90: 			usingForce = false;
91: 		}
92: 		if (usingForce) {
93: 			int level = getBuffedBonus(hero, Force.class);
94: 			float tier = tier(hero.STR());
95: 			int dmg = Hero.heroDamageIntRange(min(level, tier), max(level, tier));
96: 			if (hero.buff(BrawlersStance.class) != null
97: 				&& hero.buff(BrawlersStance.class).active){
98: 				// 3+tier base dmg, roughly +60%->45% dmg at T1->5
99: 				// lvl*((4+2*tier)/8) scaling, +50% dmg
100: 				dmg += Math.round(3+tier+(level*((4+2*tier)/8f)));
101: 			}
102: 			return dmg;
103: 		} else {
104: 			//attack without any ring of force influence
105: 			return Hero.heroDamageIntRange(1, Math.max(hero.STR()-8, 1));
106: 		}
107: 	}
